<?php require_once '../config.php'; login_required('admin');
function count_sql($sql){global $conn; return mysqli_fetch_assoc(mysqli_query($conn,$sql))['total'];}
$books=count_sql('SELECT COALESCE(SUM(quantity),0) total FROM books');$available=count_sql('SELECT COALESCE(SUM(available),0) total FROM books');$issued=count_sql("SELECT COUNT(*) total FROM issues WHERE status!='Returned'");$members=count_sql("SELECT COUNT(*) total FROM users WHERE role='user'");$fine=count_sql('SELECT COALESCE(SUM(fine),0) total FROM issues');
